CREATE TABLE catalog_category_fixture_manifest (
    manifest_id VARCHAR(80) PRIMARY KEY,
    status VARCHAR(24) NOT NULL,
    notes TEXT NOT NULL,
    recorded_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT ck_catalog_category_fixture_manifest_status
        CHECK (status IN ('PENDING_REVIEW', 'ACTIVE')),
    CONSTRAINT ck_catalog_category_fixture_manifest_notes CHECK (btrim(notes) <> '')
);

CREATE FUNCTION catalog_assert_category_fixture_integrity()
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM catalog_main_category main_category
        JOIN catalog_subcategory subcategory
            ON subcategory.id = main_category.id
    ) THEN
        RAISE EXCEPTION 'catalog main category and subcategory id sets must not intersect'
            USING ERRCODE = '23514';
    END IF;
END;
$$;

CREATE FUNCTION catalog_guard_category_fixture_integrity()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    PERFORM catalog_assert_category_fixture_integrity();

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_catalog_main_category_fixture_integrity
AFTER INSERT OR UPDATE OR DELETE ON catalog_main_category
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
EXECUTE FUNCTION catalog_guard_category_fixture_integrity();

CREATE CONSTRAINT TRIGGER trg_catalog_subcategory_fixture_integrity
AFTER INSERT OR UPDATE OR DELETE ON catalog_subcategory
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
EXECUTE FUNCTION catalog_guard_category_fixture_integrity();

